// Health-check registry. gutted, merciless, onalert retired from the OS control plane 2026-07-06 (Krish directive).
// plinth + full-time onboarded with verified repo/Vercel/live-URL facts (2026-07-06). [RETIRED 2026-08-11: Plinth was renamed Legibility 2026-08-07 and then retired; it has zero customers and no live Stripe path.]
return [
  { json: { app_name: 'mm-ctrl', repo: 'mm-ctrl', live_url: 'https://mindmaker-for-leaders.vercel.app', venture: 'mindmaker', vercel_project: 'mindmaker-for-leaders', routes: ['/', '/dashboard', '/booking', '/today'] } },
  { json: { app_name: 'fractionl-circle', repo: 'fractionl-circle', live_url: 'https://fractionl-circle.vercel.app', venture: 'fractionl', vercel_project: 'fractionl-circle', routes: ['/', '/share-contact'] } },
  { json: { app_name: 'fractionl-pulse', repo: 'fractionl-pulse', live_url: 'https://fractionl-pulse.vercel.app', venture: 'fractionl', vercel_project: 'fractionl-pulse', routes: ['/', '/login'] } },
  { json: { app_name: 'mindmaker', repo: 'mindmaker', live_url: 'https://mindmaker-dusky.vercel.app', venture: 'mindmaker', vercel_project: 'mindmaker-dusky', routes: ['/', '/sprints', '/builder-economy', '/blog'] } },
  { json: { app_name: 'plinth', repo: 'plinth', live_url: 'https://plinth-tan.vercel.app', venture: 'plinth', vercel_project: 'plinth', routes: ['/', '/docs', '/dashboard'] } },
  { json: { app_name: 'full-time', repo: 'full-time', live_url: 'https://full-time-alpha.vercel.app', venture: 'full-time', vercel_project: 'full-time', routes: ['/'] } }
];

const config = $('App Registry').item.json;
const urlResp = $('Check Live URL').item.json;
const ghResp = $('Fetch GitHub Repo').item.json;
const prResp = $('Fetch Open PRs').item.json;

// Vercel deployment data
let vercelStatus = 'unknown';
let vercelError = '';
try {
  const vResp = $('Check Vercel Deploy').item.json;
  const vBody = vResp.body || vResp || {};
  const deploys = vBody.deployments || [];
  if (deploys.length > 0) {
    const latest = deploys[0];
    vercelStatus = latest.readyState || latest.state || 'unknown';
    if (vercelStatus === 'ERROR' || vercelStatus === 'CANCELED') {
      vercelError = 'Vercel deploy ' + vercelStatus + (latest.inspectorUrl ? ' // ' + latest.inspectorUrl : '');
    }
  }
} catch(e) {
  vercelStatus = 'api-error';
}

// HTTP status from fullResponse
const httpStatus = urlResp.statusCode || 0;

// HTML body analysis (Layer 2)
const htmlBody = (urlResp.data || urlResp.body || '').toString().toLowerCase();
const htmlLength = htmlBody.length;
let htmlErrors = [];

if (htmlLength < 100 && httpStatus === 200) {
  htmlErrors.push('Blank/empty page (' + htmlLength + ' chars)');
}
if (htmlBody.includes('application error')) {
  htmlErrors.push('Vercel "Application error" detected');
}
if (htmlBody.includes('internal server error')) {
  htmlErrors.push('Internal Server Error in page');
}
if (htmlBody.includes('this page could not be found') || htmlBody.includes('next_not_found')) {
  htmlErrors.push('404 page detected');
}
if (htmlBody.includes('module not found') || htmlBody.includes('cannot find module')) {
  htmlErrors.push('Module not found error');
}
if (htmlBody.includes('unhandled runtime error') || htmlBody.includes('uncaught error')) {
  htmlErrors.push('Runtime error in page');
}
if (htmlBody.includes('hydration failed') || htmlBody.includes('hydration mismatch')) {
  htmlErrors.push('React hydration error');
}
if (htmlBody.includes('build error') || htmlBody.includes('failed to compile')) {
  htmlErrors.push('Build/compile error');
}

// GitHub metrics
const ghBody = ghResp.body || ghResp || {};
const openIssues = ghBody.open_issues_count || 0;
const pushedAt = ghBody.pushed_at || null;
const daysSinceCommit = pushedAt
  ? Math.floor((Date.now() - new Date(pushedAt).getTime()) / (1000 * 60 * 60 * 24))
  : -1;

// PR count
const prBody = prResp.body || prResp || [];
const openPrs = Array.isArray(prBody) ? prBody.length : 0;

// Stale PRs (>48h)
let stalePrCount = 0;
if (Array.isArray(prBody)) {
  const now = Date.now();
  for (const pr of prBody) {
    if ((now - new Date(pr.created_at).getTime()) > 48 * 60 * 60 * 1000) stalePrCount++;
  }
}

// Determine system status
let systemStatus = 'healthy';
let notes = [];

if (httpStatus === 0 || httpStatus >= 500) {
  systemStatus = 'down';
  notes.push('HTTP ' + httpStatus);
} else if (vercelStatus === 'ERROR' || vercelStatus === 'CANCELED') {
  systemStatus = 'deploy-failed';
  notes.push(vercelError);
} else if (httpStatus >= 400) {
  systemStatus = 'error';
  notes.push('HTTP ' + httpStatus);
} else if (htmlErrors.length > 0) {
  systemStatus = 'broken';
  notes = notes.concat(htmlErrors);
} else if (daysSinceCommit > 14) {
  systemStatus = 'stale';
  notes.push('No commits in ' + daysSinceCommit + ' days');
} else if (openPrs > 3 || stalePrCount > 0) {
  systemStatus = 'attention';
  if (stalePrCount > 0) notes.push(stalePrCount + ' stale PRs (>48h)');
  if (openPrs > 3) notes.push(openPrs + ' open PRs');
}

if (daysSinceCommit > 7 && systemStatus === 'healthy') {
  notes.push('Last commit ' + daysSinceCommit + ' days ago');
}

const visualStatus = htmlErrors.length > 0 ? 'html-errors-detected' : 'pending';

return {
  json: {
    app_name: config.app_name,
    repo: config.repo,
    live_url: config.live_url,
    venture: config.venture,
    http_status: httpStatus,
    response_time_ms: 0,
    system_status: systemStatus,
    days_since_last_commit: daysSinceCommit,
    open_issues: openIssues,
    open_prs: openPrs,
    visual_test_status: visualStatus,
    notes: notes.length > 0 ? notes.join('; ') : 'OK',
    vercel_status: vercelStatus,
    routes_checked: config.routes || ['/']
  }
};

const items = $('Calculate Health Metrics').all();
const today = new Date().toISOString().split('T')[0];

let broken = [];
let stale = [];
let attention = [];
let healthy = 0;

for (const item of items) {
  const d = item.json;
  if (['down','error','broken','deploy-failed'].includes(d.system_status)) {
    broken.push(d.app_name + ' (' + d.notes + ')');
  } else if (d.system_status === 'stale') {
    stale.push(d.app_name + ' (' + d.days_since_last_commit + 'd)');
  } else if (d.system_status === 'attention') {
    attention.push(d.app_name + ' (' + d.notes + ')');
  } else {
    healthy++;
  }
}

let alertText = '';
let hasCritical = false;

if (broken.length > 0) {
  alertText += 'DOWN/BROKEN: ' + broken.join(', ') + '\n';
  hasCritical = true;
}
if (stale.length > 0) {
  alertText += 'STALE: ' + stale.join(', ') + '\n';
}
if (attention.length > 0) {
  alertText += 'ATTENTION: ' + attention.join(', ') + '\n';
}
alertText += healthy + '/' + items.length + ' apps healthy';

const telegramText = 'Priya Health Scan // ' + today + '\n\n' + alertText;

return [{ json: {
  has_critical: hasCritical,
  has_alerts: broken.length > 0 || stale.length > 0 || attention.length > 0,
  broken_count: broken.length,
  stale_count: stale.length,
  attention_count: attention.length,
  healthy_count: healthy,
  total_apps: items.length,
  alert_text: alertText,
  telegram_text: telegramText,
  today: today,
  bug_reports: items.filter(i => ['down','error','broken','deploy-failed'].includes(i.json.system_status)).map(i => i.json)
}}];

const data = $('Build Alert Summary').first().json;
const allApps = $('Calculate Health Metrics').all();
const today = data.today;
const broken = allApps.filter(i => ['down','error','broken'].includes(i.json.system_status));

if (broken.length === 0) {
  return [{ json: { has_docs: false } }];
}

let docTitle = 'Priya Bug Report // ' + today + ' // ' + broken.length + ' issues';
let docBody = 'PRIYA AUTOMATED BUG REPORT\n';
docBody += 'Generated: ' + new Date().toISOString() + '\n';
docBody += 'Issues found: ' + broken.length + '\n\n';
docBody += '='.repeat(50) + '\n\n';

for (const item of broken) {
  const app = item.json;
  docBody += 'APP: ' + app.app_name + '\n';
  docBody += 'Repo: krishanraja/' + app.repo + '\n';
  docBody += 'URL: ' + app.live_url + '\n';
  docBody += 'Status: ' + app.system_status + ' (HTTP ' + app.http_status + ')\n';
  docBody += 'Issue: ' + app.notes + '\n';
  docBody += 'Days since commit: ' + app.days_since_last_commit + '\n\n';

  // Claude Code CLI prompt
  docBody += 'CLAUDE CODE FIX PROMPT:\n';
  docBody += '-'.repeat(40) + '\n';
  docBody += 'cd ~/repos/' + app.repo + ' && claude code "Fix: ' + app.notes.replace(/"/g, "'") + '. ';
  docBody += 'The app at ' + app.live_url + ' is returning HTTP ' + app.http_status + '. ';

  if (app.system_status === 'broken') {
    docBody += 'The page HTML contains error indicators. Check for build errors, missing environment variables, or broken imports. ';
  } else if (app.system_status === 'down') {
    docBody += 'The site is completely down. Check Vercel deployment logs, serverless function errors, and any recent commits that may have broken the build. ';
  }

  docBody += 'Review the docs/ folder for project context. Check the last 5 commits for what changed. Propose a fix and explain what caused the issue."\n';
  docBody += '-'.repeat(40) + '\n\n';
  docBody += '='.repeat(50) + '\n\n';
}

return [{ json: { 
  has_docs: true, 
  doc_title: docTitle, 
  doc_body: docBody,
  broken_count: broken.length,
  today: today
}}];

