// Build Audit payload for Priya daily health scan
const d = $input.first().json;
const checked = d.products_checked || d.products || 0;
const issues = d.issues_found || d.issues || 0;
const brief = d.issues_brief || d.brief || '';

const suffix = brief ? `: ${brief}` : '';
return [{
  json: {
    audit_payload: {
      actor: 'priya',
      event_type: 'health-scan-daily',
      display_message: `Priya daily health scan: ${checked} products checked, ${issues} issues${suffix}.`,
      details: JSON.stringify({ products_checked: checked, issues_found: issues, brief })
    }
  }
}];

// CLO-001 guard: skip task creation when no broken+stale issues.
// Telegram alert (upstream of this node) still fires. Attention-only
// scans no longer generate a queued health-alert task per day.
{
  const _bas = $('Build Alert Summary').first().json || {};
  if ((_bas.broken_count || 0) === 0 && (_bas.stale_count || 0) === 0) {
    return [];
  }
}


// Priya Daily: map weekly_goal_id based on alert summary.
const goalsRaw = $('Read Weekly Goals').first().json;
const goalsArr = Array.isArray(goalsRaw) ? goalsRaw : (goalsRaw.data || [goalsRaw]);
const goals = goalsArr.filter(g => g && g.id);
const bas = $('Build Alert Summary').first().json || {};

function pickGoalId(text) {
  if (!text || !goals.length) return null;
  const hay = String(text).toLowerCase();
  let best = null, bestLen = 0;
  for (const g of goals) {
    for (const c of [g.title, g.current].filter(Boolean)) {
      for (const tok of String(c).toLowerCase().split(/[^a-z0-9]+/).filter(t => t.length >= 4)) {
        if (hay.includes(tok) && tok.length > bestLen) { best = g.id; bestLen = tok.length; }
      }
    }
  }
  return best;
}

const text = (bas.alert_text || '') + ' health alert product ops';
const weekly_goal_id = pickGoalId(text);
return $input.all().map(item => ({ json: { ...(item.json||{}), weekly_goal_id } }));
